import Foundation

/// Learned "which word did you mean?" model: a score for each candidate word (higher = more likely),
/// from 9 facts about it. Generated by `tools/train learn-rank`. Don't edit by hand; retrain instead.
/// Facts, in order: slip cost, word frequency, fits left word, fits right word, length change, same first letter, same last letter, stopped one key short, contraction, left association, right association.
enum RankModel {
    static var forceOff = false   // training/testing: use the hand-written formula instead
    static var isTrained: Bool { !weights.isEmpty && !forceOff }

    static let mean: [Double] = [1.477195, 6.602696, 0.268101, 0.228822, 1.081555, 0.399310, 0.444913, 0.004556, 0.002607, 0.177894, 0.148656]
    static let scale: [Double] = [0.463093, 1.224502, 0.853663, 0.794245, 0.786622, 0.489757, 0.496956, 0.067344, 0.050995, 0.618125, 0.566504]
    static let weights: [Double] = [-3.113355, 1.767915, -0.345224, -0.435827, -0.536335, 0.636418, 0.577668, 0.080113, 0.021934, 0.855934, 0.841365]

    static func score(_ x: [Double]) -> Double {
        var z = 0.0
        for i in 0..<weights.count { z += weights[i] * (x[i] - mean[i]) / scale[i] }
        return z
    }
}
